{
  "verdict": "pended",
  "governing_rule": "MP-ORT-001",
  "reason": "Coverage, network, and diagnosis checks all pass, but the clinical documentation submitted does not meet the medical necessity criteria for total knee arthroplasty. There is no mention of weight-bearing radiographs showing Kellgren-Lawrence grade 3/4 changes, no documented trial of at least three months of conservative management (e.g., physical therapy, medications, injections, assistive devices), and no documentation of preoperative medical evaluation confirming surgical candidacy. Additional information is needed before a determination can be made.",
  "missing_information": [
    "Recent (within 12 months) weight-bearing knee radiographs demonstrating Kellgren-Lawrence grade 3 or 4 changes",
    "Documentation of at least 3 months of conservative management with at least two modalities (PT, medication, injections, assistive device, weight management) including duration and outcome",
    "Documentation of preoperative medical evaluation and surgical candidacy assessment, including comorbidities affecting operative risk"
  ]
}
